/**************************************************************/
/*                                                            */
/*  RptSummaryRecord                                          */
/*                                                            */
/**************************************************************/
/*
RptSummaryRecord ::= SEQUENCE {
   regTravelTime [0] INTEGER (1..3600) OPTIONAL,
     -- Total travel time to traverse the region in seconds
   regVehDistTraveled [1] INTEGER (1..500) OPTIONAL,
     -- Total vehicle distance traveled in kilometers
   regVehTimeTraveled [2] INTEGER (1..3600) OPTIONAL,
     -- Total vehicle time traveled within the region (seconds)
   fuelConsumption [3] INTEGER (1..255) OPTIONAL,
     -- Total fuel consumption in liters
   totalVehEmissions [4] RptEmissions OPTIONAL,
     -- Total vehicle emissions
   numOfLowSpeedEvents [5] INTEGER (1..255) OPTIONAL, -- Low speed threshold
     -- Number of times speed dropped below a low speed threshold
   timeStopped [6] INTEGER (1..36000) OPTIONAL,
     -- Total Stopped time in tenths of seconds up to an hour
   numOfStopped [7] INTEGER (1..255) OPTIONAL,
     -- Number of times the speed fell below the specified stopped threshold
   locOfStops [8] RptLocOfStops OPTIONAL,
     -- Each location and duration in seconds where the speed drops below
     -- the specified stopped threshold
   regNumOfVehPassed [9] INTEGER (1..255) OPTIONAL,
     -- Number of vehicles passed over the configuration region
   regNumOfSurpassedVeh [10] INTEGER (1..255) OPTIONAL,
     -- Number of vehicles that passed the recording vehicle over the configuration region
   totalMsgsReceived [11] INTEGER (1..255) OPTIONAL,
   ...
}
*/
struct EXTERN ASN1T_RptSummaryRecord {
   struct {
      OSUINT8 regTravelTimePresent : 1;
      OSUINT8 regVehDistTraveledPresent : 1;
      OSUINT8 regVehTimeTraveledPresent : 1;
      OSUINT8 fuelConsumptionPresent : 1;
      OSUINT8 totalVehEmissionsPresent : 1;
      OSUINT8 numOfLowSpeedEventsPresent : 1;
      OSUINT8 timeStoppedPresent : 1;
      OSUINT8 numOfStoppedPresent : 1;
      OSUINT8 locOfStopsPresent : 1;
      OSUINT8 regNumOfVehPassedPresent : 1;
      OSUINT8 regNumOfSurpassedVehPresent : 1;
      OSUINT8 totalMsgsReceivedPresent : 1;
   } m;
   OSUINT16 regTravelTime;
   OSUINT16 regVehDistTraveled;
   OSUINT16 regVehTimeTraveled;
   OSUINT8 fuelConsumption;
   ASN1T_RptEmissions totalVehEmissions;
   OSUINT8 numOfLowSpeedEvents;
   OSUINT16 timeStopped;
   OSUINT8 numOfStopped;
   ASN1T_RptLocOfStops locOfStops;
   OSUINT8 regNumOfVehPassed;
   OSUINT8 regNumOfSurpassedVeh;
   OSUINT8 totalMsgsReceived;
   ASN1TSeqExt extElem1;
   ASN1T_RptSummaryRecord ();
} ;

